@Appender('\nExamples\n--------\n>>> ser = pd.Series([390., 350., 30., 20.],\n...                 index=[\'Falcon\', \'Falcon\', \'Parrot\', \'Parrot\'], name="Max Speed")\n>>> ser\nFalcon    390.0\nFalcon    350.0\nParrot     30.0\nParrot     20.0\nName: Max Speed, dtype: float64\n>>> ser.groupby(["a", "b", "a", "b"]).mean()\na    210.0\nb    185.0\nName: Max Speed, dtype: float64\n>>> ser.groupby(level=0).mean()\nFalcon    370.0\nParrot     25.0\nName: Max Speed, dtype: float64\n>>> ser.groupby(ser > 100).mean()\nMax Speed\nFalse     25.0\nTrue     370.0\nName: Max Speed, dtype: float64\n\n**Grouping by Indexes**\n\nWe can groupby different levels of a hierarchical index\nusing the `level` parameter:\n\n>>> arrays = [[\'Falcon\', \'Falcon\', \'Parrot\', \'Parrot\'],\n...           [\'Captive\', \'Wild\', \'Captive\', \'Wild\']]\n>>> index = pd.MultiIndex.from_arrays(arrays, names=(\'Animal\', \'Type\'))\n>>> ser = pd.Series([390., 350., 30., 20.], index=index, name="Max Speed")\n>>> ser\nAnimal  Type\nFalcon  Captive    390.0\n        Wild       350.0\nParrot  Captive     30.0\n        Wild        20.0\nName: Max Speed, dtype: float64\n>>> ser.groupby(level=0).mean()\nAnimal\nFalcon    370.0\nParrot     25.0\nName: Max Speed, dtype: float64\n>>> ser.groupby(level="Type").mean()\nType\nCaptive    210.0\nWild       185.0\nName: Max Speed, dtype: float64\n')
@Appender(generic._shared_docs['groupby'] % _shared_doc_kwargs)
def groupby(self, by=None, axis=0, level=None, as_index: bool=True, sort: bool=True, group_keys: bool=True, squeeze: bool=False, observed: bool=False) -> 'groupby_generic.SeriesGroupBy':
    if level is None and by is None:
        raise TypeError("You have to supply one of 'by' and 'level'")
    axis = self._get_axis_number(axis)
    return groupby_generic.SeriesGroupBy(obj=self, keys=by, axis=axis, level=level, as_index=as_index, sort=sort, group_keys=group_keys, squeeze=squeeze, observed=observed)